  gen_random_uuid(),
  'Office Chat: Conditionals',
  'Pick the right conditional in workplace chats.',
  'grammar',
  'B2',
  'hard',
  'Read each chat bubble and choose the best conditional form.',
  '{"prompt":"Conditionals at work","questions":[{"question":"Slack ping: “If the client _____ late again, we’ll reschedule the demo.”","options":["is","will be","would be","were being","be","has been being"],"correctIndex":0,"explanation":"First conditional: if + present, will + verb."},{"question":"Mentor chat: “If I _____ you, I’d send the deck tonight—not tomorrow.”","options":["were","am","be","was being","will be","been"],"correctIndex":0,"explanation":"Second conditional advice often uses were for all persons."},{"question":"Post-mortem: “If we _____ the brief earlier, we wouldn’t be rushing now.”","options":["had started","start","would start","starts","have start","starting"],"correctIndex":0,"explanation":"Third / mixed feel: if + past perfect for a past missed action."},{"question":"Legal note: “Unless she _____, we can’t publish the case study.”","options":["approves","approve","will approve","approving","approved will","to approve"],"correctIndex":0,"explanation":"Unless = if not; use present simple after unless here."},{"question":"IT desk: “I wish the printer _____ working before the board call.”","options":["were","is","be","will","being","was be"],"correctIndex":0,"explanation":"Wish + past (were) for a present unreal situation."},{"question":"Zero conditional fact on the fridge: “If ice _____, it melts.”","options":["heats","will heat","heated","heating","heat will","is heat"],"correctIndex":0,"explanation":"Facts: if + present, present."},{"question":"Formal calendar note: “_____ it rain, the rooftop picnic moves indoors.”","options":["Should","Would","Might","Can","Will","Does"],"correctIndex":0,"explanation":"Should + subject = formal if."},{"question":"Mixed conditional: “If I had saved more last year, I _____ less stressed now.”","options":["would be","will be","am","was","have been","would have being"],"correctIndex":0,"explanation":"Past condition → present result: would + base verb."},{"question":"Product owner: “We’ll ship Friday _____ QA finds a blocker.”","options":["unless","if not unless","despite","although when","because if","while unless"],"correctIndex":0,"explanation":"Unless introduces the exception that stops the plan."},{"question":"Which is a correct second conditional?","options":["If the vendor lowered the price, we would renew","If the vendor lowers the price, we would renew yesterday","If the vendor would lower the price, we renew","If the vendor lower the price, we will would renew","If vendor lowered, we renew will","If the vendor will lower, we would renewing"],"correctIndex":0,"explanation":"If + past, would + base verb."},{"question":"As soon as the NDA _____, please upload the files.","options":["is signed","will be signed","would sign","signing","signed will","be signing"],"correctIndex":0,"explanation":"Time clause after as soon as uses present (passive) for future meaning."},{"question":"“If only we _____ the timezone before inviting Tokyo.”","options":["had checked","check","will check","are checking","checks","checking had"],"correctIndex":0,"explanation":"If only + past perfect regrets a past action."}]}'::jsonb,
  null,
