  'Detective Notes: Present Perfect',
  'Solve clue cards with present perfect vs past simple.',
  'grammar',
  'B1',
  'medium',
  'Choose the form that fits each timeline clue.',
  '{"prompt":"Present perfect detective","questions":[{"question":"Crime scene card: “Someone _____ the window—glass is still on the carpet.”","options":["has broken","broke yesterday only forever","breaking","break","is break","had break"],"correctIndex":0,"explanation":"Present perfect for a past action with a present result."},{"question":"Notebook: “I _____ three witnesses today (and I may talk to more).”","options":["have interviewed","interview","am interview","interviewing always","interviewed have","was interview"],"correctIndex":0,"explanation":"Unfinished time period (today) → present perfect."},{"question":"Finished time stamp: “She _____ the evidence locker last night at 11.”","options":["closed","has closed","have closed","closing","close","was close"],"correctIndex":0,"explanation":"Past simple with a finished past time (last night)."},{"question":"Interrogation: “_____ you ever _____ a forged badge before?”","options":["Have / seen","Did / see ever always","Are / seeing","Do / saw","Has / see","Have / saw"],"correctIndex":0,"explanation":"Have you ever + past participle."},{"question":"Radio: “The suspect hasn’t arrived _____.”","options":["yet","already yesterday","never last year","ago","since night only","for yesterday"],"correctIndex":0,"explanation":"Yet is common in negative present-perfect waiting contexts."},{"question":"Stakeout log: “They _____ in this café since Monday.”","options":["have been","are being","was","be","were being always","been"],"correctIndex":0,"explanation":"Have been + since + starting point."},{"question":"Which pair is grammatically wrong?","options":["I have saw him near the alley","I have seen him near the alley","She has gone to HQ","We have finished the report","He has just left","They have never confessed"],"correctIndex":0,"explanation":"“Have saw” is incorrect; use seen."},{"question":"“Just” in detective English often pairs with…","options":["present perfect","future only","imperative only","gerund only","past continuous forever","modal of"],"correctIndex":0,"explanation":"Have just + past participle = very recent past."},{"question":"“This is the first time I _____ this handwriting.”","options":["have analysed","analyse","am analyse","analysing","was analyse","analyse have"],"correctIndex":0,"explanation":"This is the first time + present perfect."},{"question":"Choose the best contrast: result now vs finished story.","options":["Someone has taken the key / Someone took the key at 9pm","Someone takes the key / Someone taking the key at 9pm","Someone taken has the key / Someone take the key at 9pm","Someone is take the key / Someone have took at 9pm","Someone took has the key / Someone has took at 9pm","Someone taking key / Someone tooked the key at 9pm"],"correctIndex":0,"explanation":"Present perfect = present relevance; past simple = finished time."},{"question":"Lab note: “We _____ the DNA results yet—still processing.”","options":["haven''t received","didn''t received","don''t receive yet always","aren''t receive","hasn''t receiving","not have receive"],"correctIndex":0,"explanation":"Haven’t + past participle + yet."}]}'::jsonb,
