  '{"prompt":"Past simple picnic","questions":[{"question":"Picnic opener: “Yesterday we _____ to the sunny park by the lake.”","options":["went","go","goed","going","goes","gone"],"correctIndex":0,"explanation":"Go → went in past simple."},{"question":"Maya _____ peanut-butter sandwiches for everyone.","options":["made","maked","make","making","makes","maded"],"correctIndex":0,"explanation":"Make → made (irregular)."},{"question":"Disaster line: “The dog _____ the whole chocolate cake!”","options":["ate","eated","eat","eats","eating","aten"],"correctIndex":0,"explanation":"Eat → ate in past simple."},{"question":"We _____ so loud that a duck stared at us.","options":["laughed","laugh","laughs","laughing","laughs did","laught"],"correctIndex":0,"explanation":"Regular verb: laugh → laughed."},{"question":"Weather note: “It _____ sunny all afternoon.”","options":["was","were","is","be","been","been"],"correctIndex":0,"explanation":"It + was for past description."},{"question":"Negative: “We _____ stay late because of the ants.”","options":["didn''t","doesn''t","don''t","isn''t","wasn''t","aren''t"],"correctIndex":0,"explanation":"Past negative: didn’t + base verb."},{"question":"Question: “_____ you see the ant parade near the blanket?”","options":["Did","Do","Does","Are","Was","Have"],"correctIndex":0,"explanation":"Past yes/no question: Did + subject + base verb."},{"question":"Leo _____ his lemonade when a bee arrived.","options":["spilled","spill","spills","spilling","spilleds","spilted always"],"correctIndex":0,"explanation":"Spill → spilled (regular) in this story."},{"question":"Choose the correct past sentence.","options":["They played football after lunch","They play football after lunch yesterday","They playing football after lunch","They plays football after lunch","They did played football after lunch","They was play football after lunch"],"correctIndex":0,"explanation":"Subject + past verb (played)."}]}'::jsonb,
